def compute(vars):
    vested_value = vars["v1"]
    net_earnings = vars["v2"]
    if net_earnings == 0:
        return None
    percentage = vested_value / net_earnings * 100
    return {
        "value": percentage,
        "trace": {
            "vested_value": vested_value,
            "net_earnings": net_earnings,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
